#!/usr/bin/env python3
# luxarch:worktree-git hook v2 - DO NOT edit this file - it is emitted by `luxarch --emit hooks`; re-emit to update.
"""How the worktree hook calls git: a literal-pathspec call on one checkout, with the variables that
point git at another repository removed, and a call to origin that cannot prompt or hang. And where
an agent's worktree lives (`agents_home`, `agent_dirs`).

Python 3.9 and the standard library only, like the hook that loads it.
"""

from __future__ import annotations

import os
import subprocess
import tempfile
from pathlib import Path

# The variables that point git at a repository other than the one at `-C`. Exported (a session run
# from inside a git hook, a shell that set GIT_DIR), `--absolute-git-dir` in a worktree named the main
# checkout's git dir, and prune deleted the main checkout's submodule clones as the worktree's (v12).
GIT_LOCATION = (
    "GIT_DIR",
    "GIT_WORK_TREE",
    "GIT_COMMON_DIR",
    "GIT_INDEX_FILE",
    "GIT_OBJECT_DIRECTORY",
    "GIT_ALTERNATE_OBJECT_DIRECTORIES",
    "GIT_NAMESPACE",
    "GIT_CEILING_DIRECTORIES",
)


# Agent worktrees live beside the repository, never inside it: `<repo parent>/.worktrees/<repo>/<KEY>`.
# Claude Code loads the skills of a `.claude/skills/` below the directory a session started in once
# it reads a file there, so a worktree inside the checkout put a scoped copy of every skill on its
# branch (possibly an older one) into the main session's skill list, and kept it after the worktree
# was gone. A directory beside the checkout is below nothing the session started in.
# Two repositories never share a home: two directories in one parent never share a name. What can
# sit at a home's `<KEY>` is a directory git does not list for this repository (a removed clone's
# worktree, a copy): `create` refuses it, never reuses it.
# a path that cannot be resolved (gone, a link loop, a NUL in it)
_PATH_ERRORS = (OSError, RuntimeError, ValueError)
AGENTS_DIR = ".worktrees"
# Where Claude Code's own EnterWorktree created them: still listed, landed, adopted and pruned, so a
# worktree made before the move is never stranded, but nothing is created there.
LEGACY_AGENTS = (".claude", "worktrees")


def agents_home(main: Path) -> Path:
    """`<repo parent>/.worktrees/<repo>`: where this repository's agent worktrees are created."""
    return main.parent / AGENTS_DIR / main.name


def agent_dirs(main: Path) -> tuple[Path, Path]:
    """Every directory an agent worktree of this repository can sit in: its home, then the in-repo
    `.claude/worktrees/` of worktrees made before the move."""
    return agents_home(main), main.joinpath(*LEGACY_AGENTS)


def in_agent_dir(main: Path, path: Path) -> bool:
    """`path` sits directly in one of `agent_dirs(main)`, as written or with links resolved."""
    dirs = agent_dirs(main)
    if path.parent in dirs:
        return True
    try:
        return path.resolve().parent in {d.resolve() for d in dirs}
    except _PATH_ERRORS:
        return False


def listed_worktrees(main: Path) -> set[Path]:
    """Every worktree path `git worktree list` gives for `main`, as written and with links resolved."""
    rows: set[Path] = set()
    for line in out(main, "worktree", "list", "--porcelain").splitlines():
        if line.startswith("worktree "):
            p = Path(line[len("worktree ") :])
            rows.add(p)
            try:
                rows.add(p.resolve())
            except _PATH_ERRORS:
                continue
    return rows


def is_listed(path: Path, listed: set[Path]) -> bool:
    if path in listed:
        return True
    try:
        return path.resolve() in listed
    except _PATH_ERRORS:
        return False


def agent_worktree(main: Path, key: str) -> Path:
    """The one place the agent worktree `key` is: the candidate (its home, then `.claude/worktrees/`
    from before the move) that `git worktree list` lists for `main`; with neither listed, its home,
    where it is created. A directory git does not list (a remove that left a file behind, a copy)
    is never the worktree."""
    listed = listed_worktrees(main)
    for d in agent_dirs(main):
        try:
            if is_listed(d / key, listed) and (d / key).is_dir():
                return d / key
        except _PATH_ERRORS:
            break
    return agents_home(main) / key


def git_env(**extra: str) -> dict[str, str]:
    env = {k: v for k, v in os.environ.items() if k not in GIT_LOCATION}
    env.update(extra)
    return env


def run(cwd: Path, *args: str) -> subprocess.CompletedProcess[str]:
    # every path handed to git is a literal path, never a pathspec: `ls-files -- :secret.env` read the
    # leading `:` as magic, so a file main tracks looked untracked and `land` deleted it (v5)
    return subprocess.run(
        ["git", "--literal-pathspecs", "-C", str(cwd), *args],
        capture_output=True,
        text=True,
        env=git_env(),
    )


def out(cwd: Path, *args: str) -> str:
    r = run(cwd, *args)
    return r.stdout.strip() if r.returncode == 0 else ""


def net_limit(push: bool) -> float:
    """Seconds a call to origin may take. A fetch or ls-remote gets `LUXARCH_LAND_TIMEOUT` (60 by
    default). A push gets `LUXARCH_LAND_PUSH_TIMEOUT` (1800 by default): it runs the repo's own
    pre-push hook, a secret scan of the whole history or an image build, which grows with the repo,
    and the fetch just before it has already shown that origin answers."""
    name, default = (
        ("LUXARCH_LAND_PUSH_TIMEOUT", 1800.0)
        if push
        else ("LUXARCH_LAND_TIMEOUT", 60.0)
    )
    try:
        return float(os.environ.get(name, default))
    except ValueError:
        return default


def run_net(
    cwd: Path, *args: str, push: bool = False
) -> subprocess.CompletedProcess[str]:
    """A git call that talks to origin: no terminal prompt, no stdin, and a timeout (`net_limit`), so
    an unanswering origin or a prompt reads as unreachable instead of hanging. The repo's own ssh
    settings (`core.sshCommand`) stay in force. git writes to files, not pipes, so the wait is for
    git itself: a process a pre-push hook leaves behind cannot hold the call open. git stays in this
    process's group, so an interrupt or a hangup stops it with `land`."""
    limit = net_limit(push)
    with tempfile.TemporaryFile() as o, tempfile.TemporaryFile() as e:
        try:
            r = subprocess.run(
                ["git", "--literal-pathspecs", "-C", str(cwd), *args],
                stdout=o,
                stderr=e,
                stdin=subprocess.DEVNULL,
                env=git_env(GIT_TERMINAL_PROMPT="0"),
                timeout=limit,
            )
        except subprocess.TimeoutExpired:
            # what git and its hooks printed before the limit says why they took so long
            o.seek(0)
            e.seek(0)
            said = (o.read() + e.read()).decode("utf-8", "replace").rstrip()
            return subprocess.CompletedProcess(
                args,
                124,
                "",
                (said + "\n" if said else "")
                + f"git {args[0]} did not answer within {limit:g}s",
            )
        o.seek(0)
        e.seek(0)
        return subprocess.CompletedProcess(
            args,
            r.returncode,
            o.read().decode("utf-8", "replace"),
            e.read().decode("utf-8", "replace"),
        )
